namespace docking.widgets.table.threaded;

using ghidra.docking.spy;

public class TestThreadedTableModelListener : ThreadedTableModelListener {

	private volatile bool pending;
	private volatile bool updating;
	private volatile bool completed;
	private volatile bool cancelled;

	private SpyEventRecorder spy;
	private ThreadedTableModel<object,object> model;

	public TestThreadedTableModelListener(ThreadedTableModel<object,object> model) : this(model, new SpyEventRecorder("Listener Spy"))
    {
	}

	public TestThreadedTableModelListener(ThreadedTableModel<object,object> model, SpyEventRecorder spy) {
		this.spy = spy;
		this.model = model;
	}

	void reset(ThreadedTableModel<object,object> newModel) {
		spy.record("Test - listener - reset()");
		completed = cancelled = false;
	}

	bool doneWork() {
		spy.record("Test - listener - doneWork()? " + (completed || cancelled) + " - completed? " +
			completed + "; cancelled? " + cancelled);
		return completed || cancelled;
	}

	bool startedWork() {
		spy.record("Test - listener - startedWork() - updating? " + updating);
		return updating;
	}

	/* @Override */
	public void loadPending() {
		spy.record("Swing - listener - loadPending()");
		pending = true;
	}

	/* @Override */
	public void loadingStarted() {
		spy.record("Swing - listener - loadStarted()");
		updating = true;
	}

	/* @Override */
	public void loadingFinished(bool wasCancelled) {
		spy.record("Swing - listener - loadingFinished() - cancelled? " + wasCancelled +
			"; size: " + model.getRowCount());
		cancelled = wasCancelled;
		completed = !cancelled;
	}

	/* @Override */
	// @formatter:off
	public string toString() {
		return getClass().getSimpleName() + "[" +
			"pending="+ pending + 
			", updating=" + updating + 
			", completed=" + completed + 
			", cancelled=" + cancelled +
		"]";
	}
	// @formatter:on

}
